def kadane(a):
    """Nonempty input."""
    current = best = a[0]
    for value in a[1:]:
        current = max(value, current + value)
        best = max(best, current)
    return best

def circular_sum(a):
    best = kadane(a)
    if best < 0:
        return best
    return max(best, sum(a) + kadane([-x for x in a]))

