def pollard_rho(n):
    """Find one factor; deterministic retry constants, 1 < n < 2**64."""
    if n % 2 == 0:
        return 2
    if miller_rabin(n):
        return n
    constant = 1
    while True:
        slow = fast = 2
        divisor = 1
        while divisor == 1:
            slow = (slow * slow + constant) % n
            fast = (fast * fast + constant) % n
            fast = (fast * fast + constant) % n
            divisor = gcd(abs(slow - fast), n)
        if divisor != n:
            return divisor
        constant += 1

