def separators(n, edges):
    """Undirected multigraph; parent edge identity handles parallel edges."""
    graph = [[] for _ in range(n)]
    for identity, (a, b) in enumerate(edges):
        graph[a].append((b, identity))
        graph[b].append((a, identity))
