def bipartite(graph):
    color = [-1] * len(graph)
    for start in range(len(graph)):
        if color[start] != -1:
            continue
        color[start] = 0
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for child in graph[node]:
                if color[child] == -1:
                    color[child] = 1 - color[node]
                    queue.append(child)
                elif color[child] == color[node]:
                    return False
    return True

