def bloom(keys, queries, size=32):
    """No false negatives; true means possibly present, never proof of presence."""
    bits = 0
    for key in keys:
        for position in (key % size, (key * 7 + 3) % size):
            bits |= 1 << position
    result = []
    for key in queries:
        result.append(all(bits & (1 << p) for p in (key % size, (key * 7 + 3) % size)))
    return result

