def heapify(values):
    heap = list(values)
    def down(root):
        while 2 * root + 1 < len(heap):
            child = 2 * root + 1
            if child + 1 < len(heap) and heap[child + 1] < heap[child]:
                child += 1
            if heap[root] <= heap[child]:
                break
            heap[root], heap[child] = heap[child], heap[root]
            root = child
    for root in range(len(heap) // 2 - 1, -1, -1):
        down(root)
    return heap

