def brent(head):
    if head is None:
        return 0
    power, length, slow, fast = 1, 1, head, head.next
    while fast and slow is not fast:
        if power == length:
            slow = fast
            power *= 2
            length = 0
        fast = fast.next
        length += 1
    return length if fast else 0

