def list_palindrome(head):
    if not head:
        return True
    slow, fast = head, head.next
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
    second = reverse(slow.next)
    a, b, answer = head, second, True
    while b:
        if a.value != b.value:
            answer = False
        a, b = a.next, b.next
    slow.next = reverse(second)
    return answer

