def permutations(values):
    result, path, used = [], [], set()
    def visit():
        if len(path) == len(values):
            result.append(list(path))
        for i, value in enumerate(values):
            if i not in used:
                used.add(i)
                path.append(value)
                visit()
                path.pop()
                used.remove(i)
    visit()
    return result

